620                  { "telephone",  SAYAS_DIGITS1 },
   621                  { NULL,         -1 }
   622          };
   623
   624          static const MNEM_TAB mnem_sayas_format[] = {
   625                  { "glyphs", 1 },
   626                  { NULL,    -1 }
   627          };
   628
   629          static const MNEM_TAB mnem_break[] = {
   630                  { "none",     0 },
   631                  { "x-weak",   1 },
   632                  { "weak",     2 },
   633                  { "medium",   3 },
   634                  { "strong",   4 },
   635                  { "x-strong", 5 },
   636                  { NULL,      -1 }
   637          };
   638
   639          static const MNEM_TAB mnem_emphasis[] = {
   640                  { "none",     1 },
   641                  { "reduced",  2 },
   642                  { "moderate", 3 },
   643                  { "strong",   4 },
   644                  { "x-strong", 5 },
   645                  { NULL,      -1 }
   646          };
   647
   648          static const char *prosody_attr[5] = {
   649                  NULL, "rate", "volume", "pitch", "range"
   650          };
   651
   652          for (ix = 0; ix < (sizeof(tag_name)-1); ix++) {
   653                  if (((c = xml_buf[ix]) == 0) || iswspace(c))
   654                          break;
   655                  tag_name[ix] = tolower((char)c);
   656          }
   657          tag_name[ix] = 0;
   658
   659          px = &xml_buf[ix]; // the tag's attributes
   660
   661          if (tag_name[0] == '/') {
   662                  // closing tag
   663                  if ((tag_type = LookupMnem(ssmltags, &tag_name[1])) != HTML_NOSPACE)
   664                          outbuf[(*outix)++] = ' ';
   665                  tag_type += SSML_CLOSE;
   666          } else {
   667                  if ((tag_type = LookupMnem(ssmltags, tag_name)) != HTML_NOSPACE) {
   668                          // separate SSML tags from the previous word (but not HMTL tags such as <b> <font> which can occur inside a word)
   669                          outbuf[(*outix)++] = ' ';
   670                  }
   671
   672                  if (self_closing && ignore_if_self_closing[tag_type])
   673                          return 0;
   674          }
   675
   676          voice_change_flag = 0;
   677          ssml_sp = &ssml_stack[*n_ssml_stack-1];
   678
   679          switch (tag_type)
   680          {
   681          case SSML_STYLE:
   682                  sp = PushParamStack(tag_type, n_param_stack, (PARAM_STACK *) param_stack);
   683                  attr1 = GetSsmlAttribute(px, "field");
   684                  attr2 = GetSsmlAttribute(px, "mode");
   685
   686
   687                  if (attrcmp(attr1, "punctuation") == 0) {
   688                          value = attrlookup(attr2, mnem_punct);
   689                          sp->parameter[espeakPUNCTUATION] = value;
   690                  } else if (attrcmp(attr1, "capital_letters") == 0) {
   691                          value = attrlookup(attr2, mnem_capitals);
   692                          sp->parameter[espeakCAPITALS] = value;
   693                  }
   694                  ProcessParamStack(outbuf, outix, *n_param_stack, param_stack, speech_parameters);
   695                  break;
   696          case SSML_PROSODY:
   697                  sp = PushParamStack(tag_type, n_param_stack, (PARAM_STACK *) param_stack);
   698
   699                  // look for attributes:  rate, volume, pitch, range
   700                  for (param_type = espeakRATE; param_type <= espeakRANGE; param_type++) {
   701                          if ((attr1 = GetSsmlAttribute(px, prosody_attr[param_type])) != NULL)
   702                                  SetProsodyParameter(param_type, attr1, sp, param_stack, speech_parameters);
   703                  }
   704
   705                  ProcessParamStack(outbuf, outix, *n_param_stack, param_stack, speech_parameters);
   706                  break;
   707          case SSML_EMPHASIS:
   708                  sp = PushParamStack(tag_type, n_param_stack, (PARAM_STACK *) param_stack);
   709                  value = 3; // default is "moderate"
   710                  if ((attr1 = GetSsmlAttribute(px, "level")) != NULL)
   711                          value = attrlookup(attr1, mnem_emphasis);
   712
   713                  if (translator->langopts.tone_language == 1) {
   714                          static unsigned char emphasis_to_pitch_range[] = { 50, 50, 40, 70, 90, 100 };
   715                          static unsigned char emphasis_to_volume[] = { 100, 100, 70, 110, 135, 150 };
   716                          // tone language (eg.Chinese) do emphasis by increasing the pitch range.
   717                          sp->parameter[espeakRANGE] = emphasis_to_pitch_range[value];
   718                          sp->parameter[espeakVOLUME] = emphasis_to_volume[value];
   719                  } else {
   720                          static unsigned char emphasis_to_volume2[] = { 100, 100, 75, 100, 120, 150 };
   721                          sp->parameter[espeakVOLUME] = emphasis_to_volume2[value];
   722                          sp->parameter[espeakEMPHASIS] = value;
   723                  }
   724                  ProcessParamStack(outbuf, outix, *n_param_stack, param_stack, speech_parameters);
   725                  break;
   726          case SSML_STYLE + SSML_CLOSE:
   727          case SSML_PROSODY + SSML_CLOSE:
   728          case SSML_EMPHASIS + SSML_CLOSE:
   729                  PopParamStack(tag_type, outbuf, outix, n_param_stack, (PARAM_STACK *) param_stack, (int *) speech_parameters);
   730                  break;
   731          case SSML_PHONEME:
   732                  attr1 = GetSsmlAttribute(px, "alphabet");
   733                  attr2 = GetSsmlAttribute(px, "ph");
   734                  value = attrlookup(attr1, mnem_phoneme_alphabet);
   735                  if (value == 1) { // alphabet="espeak"
   736                          outbuf[(*outix)++] = '[';
   737                          outbuf[(*outix)++] = '[';
   738                          *outix += attrcopy_utf8(&outbuf[*outix], attr2, n_outbuf-*outix);
   739                          outbuf[(*outix)++] = ']';
   740                          outbuf[(*outix)++] = ']';
   741                  }
   742                  break;
   743          case SSML_SAYAS:
   744                  attr1 = GetSsmlAttribute(px, "interpret-as");
   745                  attr2 = GetSsmlAttribute(px, "format");
   746                  attr3 = GetSsmlAttribute(px, "detail");
   747                  value = attrlookup(attr1, mnem_interpret_as);
   748                  value2 = attrlookup(attr2, mnem_sayas_format);
   749                  if (value2 == 1)
   750                          value = SAYAS_GLYPHS;
   751
   752                  value3 = attrnumber(attr3, 0, 0);
   753
   754                  if (value == SAYAS_DIGITS) {
   755                          if (value3 <= 1)
   756                                  value = SAYAS_DIGITS1;
   757                          else
   758                                  value = SAYAS_DIGITS + value3;
   759                  }
   760
   761                  sprintf(buf, "%c%dY", CTRL_EMBEDDED, value);
   762                  strcpy(&outbuf[*outix], buf);
   763                  *outix += strlen(buf);
   764
   765                  *sayas_start = *outix;
   766                  *sayas_mode = value; // punctuation doesn't end clause during SAY-AS
   767                  break;
   768          case SSML_SAYAS + SSML_CLOSE:
   769                  if (*sayas_mode == SAYAS_KEY) {
   770                          outbuf[*outix] = 0;
   771                          ReplaceKeyName(outbuf, *sayas_start, outix);
   772                  }
   773
   774                  outbuf[(*outix)++] = CTRL_EMBEDDED;
   775                  outbuf[(*outix)++] = 'Y';
   776                  *sayas_mode = 0;
   777                  break;
   778          case SSML_SUB:
   779                  if ((attr1 = GetSsmlAttribute(px, "alias")) != NULL) {
   780                          // use the alias  rather than the text
   781                          *ignore_text = true;
   782                          *outix += attrcopy_utf8(&outbuf[*outix], attr1, n_outbuf-*outix);
   783                  }
   784                  break;
   785          case SSML_IGNORE_TEXT:
   786                  *ignore_text = true;
   787                  break;
   788          case SSML_SUB + SSML_CLOSE:
   789          case SSML_IGNORE_TEXT + SSML_CLOSE:
   790                  *ignore_text = false;
   791                  break;
   792          case SSML_MARK:
   793                  if ((attr1 = GetSsmlAttribute(px, "name")) != NULL) {
   794                          // add name to circular buffer of marker names
   795                          attrcopy_utf8(buf, attr1, sizeof(buf));
   796
   797                          if (strcmp(skip_marker, buf) == 0) {
   798                                  // This is the marker we are waiting for before starting to speak
   799                                  *clear_skipping_text = true;
   800                                  skip_marker[0] = 0;
   801                                  return CLAUSE_NONE;
   802                          }
   803
   804                          if ((index = AddNameData(buf, 0)) >= 0) {
   805                                  sprintf(buf, "%c%dM", CTRL_EMBEDDED, index);
   806                                  strcpy(&outbuf[*outix], buf);
   807                                  *outix += strlen(buf);
   808                          }
   809                  }
   810                  break;
   811          case SSML_AUDIO:
   812                  sp = PushParamStack(tag_type, n_param_stack, (PARAM_STACK *)param_stack);
   813
   814                  if ((attr1 = GetSsmlAttribute(px, "src")) != NULL) {
   815                          char fname[256];
   816                          attrcopy_utf8(buf, attr1, sizeof(buf));
   817
   818                          if (uri_callback == NULL) {
   819                                  if ((xmlbase != NULL) && (buf[0] != '/')) {
   820                                          sprintf(fname, "%s/%s", xmlbase, buf);
   821                                          index = LoadSoundFile2(fname);
   822                                  } else
   823                                          index = LoadSoundFile2(buf);
   824                                  if (index >= 0) {
   825                                          sprintf(buf, "%c%dI", CTRL_EMBEDDED, index);
   826                                          strcpy(&outbuf[*outix], buf);
   827                                          *outix += strlen(buf);
   828                                          sp->parameter[espeakSILENCE] = 1;
   829                                  }
   830                          } else {
   831                                  if ((index = AddNameData(buf, 0)) >= 0) {
   832                                          uri = &namedata[index];
   833                                          if (uri_callback(1, uri, xmlbase) == 0) {
   834                                                  sprintf(buf, "%c%dU", CTRL_EMBEDDED, index);
   835                                                  strcpy(&outbuf[*outix], buf);
   836                                                  *outix += strlen(buf);
   837                                                  sp->parameter[espeakSILENCE] = 1;
   838                                          }
   839                                  }
   840                          }
   841                  }
   842                  ProcessParamStack(outbuf, outix, *n_param_stack, param_stack, speech_parameters);
   843
   844                  if (self_closing)
   845                          PopParamStack(tag_type, outbuf, outix, n_param_stack, (PARAM_STACK *) param_stack, (int *) speech_parameters);
   846                  else
   847                          *audio_text = true;
   848                  return CLAUSE_NONE;
   849          case SSML_AUDIO + SSML_CLOSE:
   850                  PopParamStack(tag_type, outbuf, outix, n_param_stack, (PARAM_STACK *) param_stack, (int *) speech_parameters);
   851                  *audio_text = false;
   852                  return CLAUSE_NONE;
   853          case SSML_BREAK:
   854                  value = 21;
   855                  terminator = CLAUSE_NONE;
   856
   857                  if ((attr1 = GetSsmlAttribute(px, "strength")) != NULL) {
   858                          static int break_value[6] = { 0, 7, 14, 21, 40, 80 }; // *10mS
   859                          value = attrlookup(attr1, mnem_break);
   860                          if (value < 3) {
   861                                  // adjust prepause on the following word
   862                                  sprintf(&outbuf[*outix], "%c%dB", CTRL_EMBEDDED, value);
   863                                  *outix += 3;
   864                                  terminator = 0;
   865                          }
   866                          value = break_value[value];
   867                  }
   868                  if ((attr2 = GetSsmlAttribute(px, "time")) != NULL) {
   869                          value2 = attrnumber(attr2, 0, 1);   // pause in mS
   870
   871                          // compensate for speaking speed to keep constant pause length, see function PauseLength()
   872                          // 'value' here is x 10mS
   873                          value = (value2 * 256) / (speed.clause_pause_factor * 10);
   874                          if (value < 200)
   875                                  value = (value2 * 256) / (speed.pause_factor * 10);
   876
   877                          if (terminator == 0)
   878                                  terminator = CLAUSE_NONE;
   879                  }
   880                  if (terminator) {
   881                          if (value > 0xfff) {
   882                                  // scale down the value and set a scaling indicator bit
   883                                  value = value / 32;
   884                                  if (value > 0xfff)
   885                                          value = 0xfff;
   886                                  terminator |= CLAUSE_PAUSE_LONG;
   887                          }
   888                          return terminator + value;
   889                  }
   890                  break;
   891          case SSML_SPEAK:
   892                  if ((attr1 = GetSsmlAttribute(px, "xml:base")) != NULL) {
   893                          attrcopy_utf8(buf, attr1, sizeof(buf));
   894                          if ((index = AddNameData(buf, 0)) >= 0)
   895                                  xmlbase = &namedata[index];
   896                  }
   897                  if (GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name) == 0)
   898                          return 0; // no voice change
   899                  return CLAUSE_VOICE;
   900          case SSML_VOICE:
   901                  if (GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name) == 0)
   902                          return 0; // no voice change
   903                  return CLAUSE_VOICE;
   904          case SSML_SPEAK + SSML_CLOSE:
   905                  // unwind stack until the previous <voice> or <speak> tag
   906                  while ((*n_ssml_stack > 1) && (ssml_stack[*n_ssml_stack-1].tag_type != SSML_SPEAK))
   907                          (*n_ssml_stack)--;
   908                  return CLAUSE_PERIOD + GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   909          case SSML_VOICE + SSML_CLOSE:
   910                  // unwind stack until the previous <voice> or <speak> tag
   911                  while ((*n_ssml_stack > 1) && (ssml_stack[*n_ssml_stack-1].tag_type != SSML_VOICE))
   912                          (*n_ssml_stack)--;
   913
   914                  terminator = 0; // ??  Sentence intonation, but no pause ??
   915                  return terminator + GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   916          case HTML_BREAK:
   917          case HTML_BREAK + SSML_CLOSE:
   918                  return CLAUSE_COLON;
   919          case SSML_SENTENCE:
   920                  if (ssml_sp->tag_type == SSML_SENTENCE) {
   921                          // new sentence implies end-of-sentence
   922                          voice_change_flag = GetVoiceAttributes(px, SSML_SENTENCE+SSML_CLOSE, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   923                  }
   924                  voice_change_flag |= GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   925                  return CLAUSE_PARAGRAPH + voice_change_flag;
   926          case SSML_PARAGRAPH:
   927                  if (ssml_sp->tag_type == SSML_SENTENCE) {
   928                          // new paragraph implies end-of-sentence or end-of-paragraph
   929                          voice_change_flag = GetVoiceAttributes(px, SSML_SENTENCE+SSML_CLOSE, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   930                  }
   931                  if (ssml_sp->tag_type == SSML_PARAGRAPH) {
   932                          // new paragraph implies end-of-sentence or end-of-paragraph
   933                          voice_change_flag |= GetVoiceAttributes(px, SSML_PARAGRAPH+SSML_CLOSE, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   934                  }
   935                  voice_change_flag |= GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   936                  return CLAUSE_PARAGRAPH + voice_change_flag;
   937          case SSML_SENTENCE + SSML_CLOSE:
   938                  if (ssml_sp->tag_type == SSML_SENTENCE) {
   939                          // end of a sentence which specified a language
   940                          voice_change_flag = GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name);
   941                  }
   942                  return CLAUSE_PERIOD + voice_change_flag;
   943          case SSML_PARAGRAPH + SSML_CLOSE:
   944                  if ((ssml_sp->tag_type == SSML_SENTENCE) || (ssml_sp->tag_type == SSML_PARAGRAPH)) {
   945                          // End of a paragraph which specified a language.
   946                          // (End-of-paragraph also implies end-of-sentence)
   947                          return GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name) + CLAUSE_PARAGRAPH;
   948                  }
   949                  return CLAUSE_PARAGRAPH;
   950          }
   951          return 0;
   952  }
