   954  static MNEM_TAB xml_entity_mnemonics[] = {
   955          { "gt",   '>' },
   956          { "lt",   0xe000 + '<' },   // private usage area, to avoid confusion with XML tag
   957          { "amp",  '&' },
   958          { "quot", '"' },
   959          { "nbsp", ' ' },
   960          { "apos", '\'' },
   961          { NULL,   -1 }
   962  };
