   964  int ParseSsmlReference(char *ref, int *c1, int *c2) {
   965          // Check if buffer *ref contains an XML character or entity reference
   966          // if found, set *c1 to the replacement char
   967          // change *c2 for entity references
   968          // returns >= 0 on success
   969
   970          if (ref[0] == '#') {
   971                  // character reference
   972                  if (ref[1] == 'x')
   973                          return sscanf(&ref[2], "%x", c1);
   974                  else
   975                          return sscanf(&ref[1], "%d", c1);
   976          } else {
   977                  // entity reference
   978                  int found;
   979                  if ((found = LookupMnem(xml_entity_mnemonics, ref)) != -1) {
   980                          *c1 = found;
   981                          if (*c2 == 0)
   982                                  *c2 = ' ';
   983                          return found;
   984                  }
   985          }
   986          return -1;
   987  }
